//! Artifact manifest, stable names and SHA-256 checksums (PRD 0021 RF2).
//!
//! `manifest.json` is the single explicit hand-off between the build jobs
//! and the assembly/publish jobs: nobody re-discovers file names ad hoc.

use std::collections::HashSet;
use std::ffi::OsStr;
use std::io::Read;
use std::path::{Component, Path, PathBuf};

use sha2::Digest;

use crate::{err, Channel, Error, Res};

/// Version of the `manifest.json` format.
pub const MANIFEST_SCHEMA: u32 = 1;

/// Files generated by the assembly itself. They are valid release assets but
/// are deliberately not listed in `manifest.artifacts`, avoiding a circular
/// self-hash.
const GENERATED_METADATA: &[&str] = &[
    "manifest.json",
    "SHA256SUMS",
    "signing-state.json",
    "SHA256SUMS.sigstore.json",
];

/// One distributable file.
#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ManifestArtifact {
    /// Stable file name (PRD 0021 RF2 table).
    pub name: String,
    /// `desktop-dmg`, `desktop-installer-nsis`, `desktop-installer-msi`,
    /// `desktop-appimage`, `desktop-deb`, `desktop-rpm`, `cli-archive`,
    /// `desktop-updater-archive`, `desktop-updater-signature`,
    /// `updater-manifest` or `sbom`.
    pub kind: String,
    /// `macos`, `windows`, `linux` or `any`.
    pub platform: String,
    /// The architecture token used in the file name.
    pub arch: String,
    pub size: u64,
    pub sha256: String,
    /// Optional artifacts may be absent without blocking the release; they
    /// are listed in `missing_optional` and in the release notes instead.
    pub optional: bool,
}

/// The assembly manifest exchanged between workflow jobs.
#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Manifest {
    pub schema: u32,
    pub version: String,
    pub channel: Channel,
    pub artifacts: Vec<ManifestArtifact>,
    /// Stable names of optional artifacts this run did not produce.
    pub missing_optional: Vec<String>,
}

/// A file the pipeline knows about, with its stable name.
struct Expected {
    name: String,
    kind: &'static str,
    platform: &'static str,
    arch: &'static str,
    optional: bool,
}

fn req(name: String, kind: &'static str, platform: &'static str, arch: &'static str) -> Expected {
    Expected {
        name,
        kind,
        platform,
        arch,
        optional: false,
    }
}

fn opt(name: String, kind: &'static str, platform: &'static str, arch: &'static str) -> Expected {
    Expected {
        name,
        kind,
        platform,
        arch,
        optional: true,
    }
}

/// The full PRD 0021 RF2 table for a version: required artifacts plus the
/// optional ARM64/updater ones that may be absent (RF2.5).
fn expected(version: &str) -> Vec<Expected> {
    let v = version;
    vec![
        // Desktop, required.
        req(
            format!("Cuotai_{v}_universal.dmg"),
            "desktop-dmg",
            "macos",
            "universal",
        ),
        req(
            format!("Cuotai_{v}_x64-setup.exe"),
            "desktop-installer-nsis",
            "windows",
            "x64",
        ),
        req(
            format!("Cuotai_{v}_x64_en-US.msi"),
            "desktop-installer-msi",
            "windows",
            "x64",
        ),
        req(
            format!("Cuotai_{v}_amd64.AppImage"),
            "desktop-appimage",
            "linux",
            "amd64",
        ),
        req(
            format!("Cuotai_{v}_amd64.deb"),
            "desktop-deb",
            "linux",
            "amd64",
        ),
        req(
            format!("Cuotai_{v}_amd64.rpm"),
            "desktop-rpm",
            "linux",
            "amd64",
        ),
        // Desktop ARM64, optional (hosted runners, RF2.5).
        opt(
            format!("Cuotai_{v}_arm64-setup.exe"),
            "desktop-installer-nsis",
            "windows",
            "arm64",
        ),
        opt(
            format!("Cuotai_{v}_aarch64.AppImage"),
            "desktop-appimage",
            "linux",
            "aarch64",
        ),
        opt(
            format!("Cuotai_{v}_aarch64.deb"),
            "desktop-deb",
            "linux",
            "aarch64",
        ),
        opt(
            format!("Cuotai_{v}_aarch64.rpm"),
            "desktop-rpm",
            "linux",
            "aarch64",
        ),
        // CLI/TUI, required.
        req(
            format!("cuotai-{v}-aarch64-apple-darwin.tar.gz"),
            "cli-archive",
            "macos",
            "aarch64",
        ),
        req(
            format!("cuotai-{v}-x86_64-apple-darwin.tar.gz"),
            "cli-archive",
            "macos",
            "x86_64",
        ),
        req(
            format!("cuotai-{v}-x86_64-unknown-linux-gnu.tar.gz"),
            "cli-archive",
            "linux",
            "x86_64",
        ),
        req(
            format!("cuotai-{v}-x86_64-unknown-linux-musl.tar.gz"),
            "cli-archive",
            "linux",
            "x86_64",
        ),
        req(
            format!("cuotai-{v}-x86_64-pc-windows-msvc.zip"),
            "cli-archive",
            "windows",
            "x86_64",
        ),
        // CLI/TUI ARM64, optional.
        opt(
            format!("cuotai-{v}-aarch64-unknown-linux-gnu.tar.gz"),
            "cli-archive",
            "linux",
            "aarch64",
        ),
        opt(
            format!("cuotai-{v}-aarch64-unknown-linux-musl.tar.gz"),
            "cli-archive",
            "linux",
            "aarch64",
        ),
        opt(
            format!("cuotai-{v}-aarch64-pc-windows-msvc.zip"),
            "cli-archive",
            "windows",
            "aarch64",
        ),
        // Updater artifacts: only when the Tauri updater key is configured.
        // The macOS archive is a tarball of the notarized app; Windows and
        // Linux are updater-signed in place, so their `.sig` sits next to the
        // installer/package itself (PRD 0018 RF1.3).
        opt(
            "Cuotai.app.tar.gz".into(),
            "desktop-updater-archive",
            "macos",
            "universal",
        ),
        opt(
            "Cuotai.app.tar.gz.sig".into(),
            "desktop-updater-signature",
            "macos",
            "universal",
        ),
        opt(
            format!("Cuotai_{v}_x64-setup.exe.sig"),
            "desktop-updater-signature",
            "windows",
            "x64",
        ),
        opt(
            format!("Cuotai_{v}_x64_en-US.msi.sig"),
            "desktop-updater-signature",
            "windows",
            "x64",
        ),
        opt(
            format!("Cuotai_{v}_arm64-setup.exe.sig"),
            "desktop-updater-signature",
            "windows",
            "arm64",
        ),
        opt(
            format!("Cuotai_{v}_amd64.AppImage.sig"),
            "desktop-updater-signature",
            "linux",
            "amd64",
        ),
        opt(
            format!("Cuotai_{v}_amd64.deb.sig"),
            "desktop-updater-signature",
            "linux",
            "amd64",
        ),
        opt(
            format!("Cuotai_{v}_amd64.rpm.sig"),
            "desktop-updater-signature",
            "linux",
            "amd64",
        ),
        opt(
            format!("Cuotai_{v}_aarch64.AppImage.sig"),
            "desktop-updater-signature",
            "linux",
            "aarch64",
        ),
        opt(
            format!("Cuotai_{v}_aarch64.deb.sig"),
            "desktop-updater-signature",
            "linux",
            "aarch64",
        ),
        opt(
            format!("Cuotai_{v}_aarch64.rpm.sig"),
            "desktop-updater-signature",
            "linux",
            "aarch64",
        ),
        opt("latest.json".into(), "updater-manifest", "any", "any"),
        // Cargo-generated release SBOM.
        req("sbom.cdx.json".into(), "sbom", "any", "any"),
    ]
}

fn safe_basename(name: &str) -> bool {
    if name.is_empty() || name.contains('/') || name.contains('\\') {
        return false;
    }
    let mut components = Path::new(name).components();
    matches!(components.next(), Some(Component::Normal(value)) if value == OsStr::new(name))
        && components.next().is_none()
}

fn validate_manifest(manifest: &Manifest) -> Res<()> {
    crate::Version::parse(&manifest.version).map_err(|e| {
        Error::Msg(format!(
            "manifest version '{}' is invalid: {e}",
            manifest.version
        ))
    })?;
    if manifest.schema != MANIFEST_SCHEMA {
        return err(format!(
            "manifest schema {} is not supported (expected {MANIFEST_SCHEMA})",
            manifest.schema
        ));
    }
    let table = expected(&manifest.version);
    let mut names = HashSet::new();
    for artifact in &manifest.artifacts {
        if !safe_basename(&artifact.name) {
            return err(format!(
                "manifest artifact name '{}' is not a safe basename",
                artifact.name
            ));
        }
        if !names.insert(artifact.name.as_str()) {
            return err(format!(
                "manifest contains duplicate artifact '{}'",
                artifact.name
            ));
        }
        let Some(spec) = table.iter().find(|spec| spec.name == artifact.name) else {
            return err(format!(
                "manifest artifact '{}' is not a stable PRD 0021 RF2 name",
                artifact.name
            ));
        };
        if artifact.kind != spec.kind
            || artifact.platform != spec.platform
            || artifact.arch != spec.arch
            || artifact.optional != spec.optional
        {
            return err(format!(
                "manifest metadata for '{}' does not match the stable artifact table",
                artifact.name
            ));
        }
        if artifact.size == 0 {
            return err(format!(
                "manifest artifact '{}' has zero size",
                artifact.name
            ));
        }
        if artifact.sha256.len() != 64
            || !artifact
                .sha256
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
        {
            return err(format!(
                "manifest artifact '{}' has an invalid lowercase SHA-256",
                artifact.name
            ));
        }
    }

    let missing_required: Vec<&str> = table
        .iter()
        .filter(|spec| !spec.optional && !names.contains(spec.name.as_str()))
        .map(|spec| spec.name.as_str())
        .collect();
    if !missing_required.is_empty() {
        return err(format!(
            "manifest omits required artifact(s): {}",
            missing_required.join(", ")
        ));
    }
    let expected_missing: Vec<&str> = table
        .iter()
        .filter(|spec| spec.optional && !names.contains(spec.name.as_str()))
        .map(|spec| spec.name.as_str())
        .collect();
    let actual_missing: Vec<&str> = manifest
        .missing_optional
        .iter()
        .map(String::as_str)
        .collect();
    if actual_missing != expected_missing {
        return err("manifest missing_optional does not exactly match absent optional artifacts");
    }
    Ok(())
}

/// Scans `dir` (flat), classifies every file against the expected stable
/// names, hashes it and returns the manifest plus the `SHA256SUMS` content.
/// Fails on unknown files and on missing required artifacts.
pub fn build_manifest(dir: &Path, version: &str, channel: Channel) -> Res<(Manifest, String)> {
    let table = expected(version);
    let mut entries: Vec<PathBuf> = Vec::new();
    for entry in std::fs::read_dir(dir)
        .map_err(|e| Error::Msg(format!("cannot read {}: {e}", dir.display())))?
    {
        let entry = entry?;
        let path = entry.path();
        let name = entry
            .file_name()
            .into_string()
            .map_err(|_| Error::Msg(format!("{}: non-UTF-8 file name", dir.display())))?;
        let metadata = std::fs::symlink_metadata(&path)?;
        if metadata.file_type().is_symlink() {
            return err(format!(
                "{}: symbolic links are not release assets",
                path.display()
            ));
        }
        if GENERATED_METADATA.contains(&name.as_str()) {
            continue;
        }
        if !metadata.is_file() {
            return err(format!(
                "{}: release asset is not a regular file",
                path.display()
            ));
        }
        entries.push(path);
    }
    entries.sort();

    let mut artifacts = Vec::new();
    for path in entries {
        let name = path
            .file_name()
            .expect("file path")
            .to_string_lossy()
            .into_owned();
        let Some(spec) = table.iter().find(|e| e.name == name) else {
            return err(format!(
                "{}: unknown file '{name}'; only the stable names of PRD 0021 RF2 are allowed",
                dir.display()
            ));
        };
        let size = std::fs::symlink_metadata(&path)?.len();
        if size == 0 {
            return err(format!("{}: release artifact is empty", path.display()));
        }
        artifacts.push(ManifestArtifact {
            name: name.clone(),
            kind: spec.kind.to_string(),
            platform: spec.platform.to_string(),
            arch: spec.arch.to_string(),
            size,
            sha256: sha256_file(&path)?,
            optional: spec.optional,
        });
    }

    let mut missing_required = Vec::new();
    let mut missing_optional = Vec::new();
    for spec in &table {
        if artifacts.iter().any(|a| a.name == spec.name) {
            continue;
        }
        if spec.optional {
            missing_optional.push(spec.name.clone());
        } else {
            missing_required.push(spec.name.clone());
        }
    }
    if !missing_required.is_empty() {
        return err(format!(
            "required artifact(s) missing from {}:\n - {}",
            dir.display(),
            missing_required.join("\n - ")
        ));
    }

    let mut sums = String::new();
    for artifact in &artifacts {
        sums.push_str(&format!("{}  {}\n", artifact.sha256, artifact.name));
    }

    Ok((
        Manifest {
            schema: MANIFEST_SCHEMA,
            version: version.to_string(),
            channel,
            artifacts,
            missing_optional,
        },
        sums,
    ))
}

/// Verifies a downloaded asset directory against a manifest: every artifact
/// is a safe regular file with the recorded size and SHA-256, and no unknown
/// payload or metadata names are present (RF4.4).
pub fn verify_download(dir: &Path, manifest: &Manifest) -> Res<usize> {
    validate_manifest(manifest)?;
    let artifact_names: HashSet<&str> = manifest
        .artifacts
        .iter()
        .map(|artifact| artifact.name.as_str())
        .collect();
    for entry in std::fs::read_dir(dir)
        .map_err(|e| Error::Msg(format!("cannot read {}: {e}", dir.display())))?
    {
        let entry = entry?;
        let name = entry
            .file_name()
            .into_string()
            .map_err(|_| Error::Msg(format!("{}: non-UTF-8 asset name", dir.display())))?;
        if !safe_basename(&name)
            || (!artifact_names.contains(name.as_str())
                && !GENERATED_METADATA.contains(&name.as_str()))
        {
            return err(format!("{}: unknown release asset '{name}'", dir.display()));
        }
        let metadata = std::fs::symlink_metadata(entry.path())?;
        if metadata.file_type().is_symlink() {
            return err(format!(
                "{}: symbolic links are not release assets",
                entry.path().display()
            ));
        }
        if !metadata.is_file() {
            return err(format!(
                "{}: release asset is not a regular file",
                entry.path().display()
            ));
        }
        if metadata.len() == 0 {
            return err(format!(
                "{}: downloaded asset is empty",
                entry.path().display()
            ));
        }
    }

    for artifact in &manifest.artifacts {
        // `validate_manifest` proved this is a single safe basename before
        // any untrusted value is joined to the download directory.
        let path = dir.join(&artifact.name);
        let meta = std::fs::symlink_metadata(&path).map_err(|e| {
            Error::Msg(format!(
                "{}: cannot stat downloaded asset: {e}",
                path.display()
            ))
        })?;
        if meta.file_type().is_symlink() || !meta.is_file() {
            return err(format!(
                "{}: downloaded asset is not a regular file",
                path.display()
            ));
        }
        if meta.len() != artifact.size {
            return err(format!(
                "{}: size {} differs from the manifest ({})",
                path.display(),
                meta.len(),
                artifact.size
            ));
        }
        let actual = sha256_file(&path)?;
        if actual != artifact.sha256 {
            return err(format!(
                "{}: sha256 {actual} differs from the manifest ({})",
                path.display(),
                artifact.sha256
            ));
        }
    }
    Ok(manifest.artifacts.len())
}

/// Parses and validates a manifest file.
pub fn load(path: &Path) -> Res<Manifest> {
    let text = std::fs::read_to_string(path)
        .map_err(|e| Error::Msg(format!("cannot read {}: {e}", path.display())))?;
    let manifest: Manifest = serde_json::from_str(&text).map_err(|e| Error::Json {
        context: path.display().to_string(),
        source: e,
    })?;
    if manifest.schema != MANIFEST_SCHEMA {
        return err(format!(
            "{}: schema {} is not supported (expected {MANIFEST_SCHEMA})",
            path.display(),
            manifest.schema
        ));
    }
    validate_manifest(&manifest).map_err(|e| Error::Msg(format!("{}: {e}", path.display())))?;
    Ok(manifest)
}

fn sha256_file(path: &Path) -> Res<String> {
    let mut file = std::fs::File::open(path)?;
    let mut digest = sha2::Sha256::new();
    let mut buffer = [0u8; 64 * 1024];
    loop {
        let read = file.read(&mut buffer)?;
        if read == 0 {
            break;
        }
        digest.update(&buffer[..read]);
    }
    Ok(hex(&digest.finalize()))
}

fn hex(bytes: &[u8]) -> String {
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(DIGITS[(byte >> 4) as usize] as char);
        out.push(DIGITS[(byte & 0x0f) as usize] as char);
    }
    out
}
